<script setup>
import { computed, reactive, watch } from 'vue'; import MButton from '../../../components/mds/MButton.vue'; import MInput from '../../../components/mds/MInput.vue'; import MMobileTopBar from '../../../components/mds/MMobileTopBar.vue'; import MTextarea from '../../../components/mds/MTextarea.vue'; import { supplierDirectDraft, supplierDirectPayload, supplierDirectSchema } from '../domain/supplier-direct-write.mjs';
const props=defineProps({kind:String,record:Object,canSeeMoney:Boolean,saving:Boolean,error:String,safeAreaStyle:Object});const emit=defineEmits(['back','save']);const schema=supplierDirectSchema(props.kind);const fields=computed(()=>schema.fields.filter((field)=>!field.confidential||props.canSeeMoney));const draft=reactive({...supplierDirectDraft(props.kind,props.record)});watch(()=>props.record,(record)=>Object.assign(draft,supplierDirectDraft(props.kind,record)));function submit(){try{emit('save',supplierDirectPayload(props.kind,draft,{existing:props.record}));}catch(error){emit('local-error',error.message);}}
</script>
<template><section class="mds-mobile-app flex h-[100dvh] min-w-0 flex-col overflow-hidden bg-[var(--mds-bg)]" :style="safeAreaStyle"><MMobileTopBar :title="`${record?'Sửa':'Thêm'} ${schema.label}`" @back="emit('back')"/><form class="min-h-0 flex-1 overflow-y-auto" @submit.prevent="submit"><div class="mds-mobile-gutter-x space-y-4 py-4"><p class="text-[13px] leading-[18px] text-[var(--mds-text-secondary)]">Quyền và số tiền do máy chủ kiểm tra lại khi lưu.</p><label v-for="field in fields" :key="field.key"><span class="mb-1 block text-[13px] font-medium">{{field.label}}<template v-if="field.required"> *</template></span><MTextarea v-if="field.multiline" v-model="draft[field.key]" :rows="3"/><MInput v-else v-model="draft[field.key]" :type="field.type||'text'" :required="field.required"/></label><p v-if="error" role="alert" class="text-[13px] text-[var(--mds-danger)]">{{error}}</p></div></form><footer class="shrink-0 border-t border-[var(--mds-border-light)] bg-[var(--mds-bg)] px-4 pb-[calc(12px+var(--mds-mobile-safe-bottom))] pt-3"><MButton variant="primary" class="w-full" :loading="saving" @click="submit">Lưu</MButton></footer></section></template>
